{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration has public IP address assignment enabled, potentially exposing instances to the internet."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly disable Instance Metadata Service Version 1, potentially allowing unauthorized access to instance metadata."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n  user_data                   = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nsudo bash -c 'echo \"[Service]\\nEnvironment=\\\"ECS_ENABLE_METADATA_V4=1\\\"\" > /etc/systemd/system/ecs.service.d/ecs-metadata-v4.conf'\nsudo systemctl daemon-reload\nsudo systemctl restart ecs\nEOF\n}",
  "fix_summary": "Disabled public IP address assignment and enabled Instance Metadata Service Version 2 by modifying user_data to include ECS_ENABLE_METADATA_V4=1"
}
